import math

def calculate_n(a, b, c):
    """Calculates the value of n for distinct positive integers a, b, c."""
    numerator = (a + b + c) * (a*b + b*c + c*a) + (a + b + c)
    denominator = 4 * a * b * c

    # Check if n is an integer
    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return None

# Parameters for the search
MAX_A = 4
MAX_C = 30

n_values = {} # To store unique n values found and their solutions

# Iterate over possible values of a
for a in range(1, MAX_A + 1):
    # Iterate over possible values of b (a < b)
    for b in range(a + 1, MAX_C):
        # Iterate over possible values of c (b < c <= MAX_C)
        for c in range(b + 1, MAX_C + 1):

            n = calculate_n(a, b, c)

            if n is not None:
                if n not in n_values:
                    n_values[n] = []
                n_values[n].append((a, b, c))

# Sort found n values to check the smallest possible integer n
sorted_n = sorted(n_values.keys())

print(f"Smallest integer n found: {sorted_n[0] if sorted_n else 'None'}")
print(f"All found integer n values: {sorted_n}")

# Print solutions for n=1, n=2, and n=3
print("\nSolutions for n=1:")
if 1 in n_values:
    print(n_values[1])
else:
    print("None found")

print("\nSolutions for n=2:")
if 2 in n_values:
    print(n_values[2])
else:
    print("None found")

print("\nSolutions for n=3:")
if 3 in n_values:
    print(n_values[3])
else:
    print("None found")

# Check if n=3 is confirmed as the smallest integer value, based on the search up to a=4, c=30
if sorted_n and sorted_n[0] == 3:
    print("\nConfirmation: Smallest n found in the search is 3.")
elif sorted_n and sorted_n[0] < 3:
    print(f"\nDisproof: Smallest n found in the search is {sorted_n[0]}, which is less than 3.")
else:
    print("\nSearch concluded without finding any integer n.")

